"use client"

import * as React from "react"
import { CircleAlert, CircleCheck, Info, Lock, TriangleAlert, Undo2, WandSparkles } from "lucide-react"

import { cn } from "@/lib/utils"
import { replaceStep, reviewMigration, type MigrationContext, type MigrationRisk, type MigrationStep } from "@/registry/default/migration-preview/review-migration"

export { replaceStep, reviewMigration, splitStatements, type MigrationContext, type MigrationLock, type MigrationRisk, type MigrationRiskKind, type MigrationStep } from "@/registry/default/migration-preview/review-migration"

const DEFAULT_MESSAGES = {
  label: "Migration",
  empty: "No statements to review.",
  steps: "{count} steps",
  steps_one: "1 step",
  irreversible: "{count} can't be undone",
  locking: "{count} hold a long lock",
  locking_one: "1 holds a long lock",
  clean: "Safe to run: no long locks, nothing lost.",
  step: "Step {n}",
  "lock-reads-writes": "Blocks reads and writes",
  "lock-writes": "Blocks writes",
  slow: "Touches every row",
  brief: "briefly",
  rows: "{rows} rows",
  cantUndo: "Can't undo",
  "drop-table": "Deletes the table and every row in it. A down migration can recreate it, not refill it.",
  "drop-column": "Deletes {detail} and its data. Code still reading {detail} breaks until it's deployed without it.",
  truncate: "Deletes every row, with no way back but a backup.",
  "delete-all": "DELETE with no WHERE removes every row.",
  "not-null-no-default": "Adding {detail} as NOT NULL with no default fails if the table has any rows.",
  "volatile-default": "{detail} is computed per row, so Postgres rewrites the whole table under a full lock.",
  "rewrite-column": "Adding {detail} this way rewrites the whole table under a full lock.",
  "type-change": "Changing the type of {detail} usually rewrites the table under a full lock.",
  "set-not-null": "SET NOT NULL scans every row while blocking reads and writes.",
  "index-blocking": "Building this index blocks every write to the table until it finishes.",
  "drop-index-blocking": "Dropping an index this way waits for, then blocks, every query on the table.",
  "concurrently-in-tx": "CONCURRENTLY can't run inside a transaction, so this step fails. Run it in its own migration.",
  "constraint-validate": "Checks every existing row while holding the lock.",
  "unique-constraint": "Builds a unique index while blocking reads and writes.",
  "rename-column": "Renaming {detail} breaks the old code still running mid-deploy. Add the new column, write both, then drop the old one.",
  "rename-table": "Renaming the table breaks the old code still running mid-deploy.",
  "update-all": "One big UPDATE locks every row it touches until it commits. Backfill in batches.",
  "lock-timeout": "No lock_timeout, so a step waiting behind a slow query blocks every query queued behind it.",
  "reindex-blocking": "Rebuilding indexes this way blocks writes, and queries that use them, until it finishes.",
  "table-rewrite": "Rewrites the whole table while blocking reads and writes.",
  "fix-index-blocking": "Use CONCURRENTLY",
  "fix-drop-index-blocking": "Use CONCURRENTLY",
  "fix-not-null-no-default": "Split into safe steps",
  "fix-volatile-default": "Split into safe steps",
  "fix-set-not-null": "Validate first",
  "fix-constraint-validate": "Add NOT VALID",
  "fix-unique-constraint": "Build index first",
  "fix-lock-timeout": "Add lock_timeout",
  "fix-reindex-blocking": "Use CONCURRENTLY",
  undo: "Undo fix",
}
export type MigrationPreviewMessages = typeof DEFAULT_MESSAGES

const fill = (text: string, values: Record<string, string | number>) => text.replace(/\{(\w+)\}/g, (match, key: string) => String(values[key] ?? match))
const tones = { danger: "text-red-700 dark:text-red-400", warning: "text-amber-700 dark:text-amber-400", info: "text-muted-foreground" }
const icons = { danger: CircleAlert, warning: TriangleAlert, info: Info }
const rank = { danger: 3, warning: 2, info: 1 }
const fixClass = (danger: boolean) =>
  cn(
    "inline-flex min-h-6 max-w-full items-center gap-1 rounded-md border px-2 text-left font-medium [overflow-wrap:anywhere] transition-colors outline-none focus-visible:ring-[3px] focus-visible:ring-ring/50",
    danger ? "border-red-500/40 text-red-800 hover:bg-red-500/10 dark:text-red-200" : "border-amber-500/40 text-amber-900 hover:bg-amber-500/10 dark:text-amber-200",
  )
const badge = "inline-flex h-5 items-center gap-1 rounded-sm border px-1.5 text-[11px] font-medium whitespace-nowrap"

/** Announces `text` only after changes settle, so screen readers don't chatter. */
function useSettled(text: string, delay = 900) {
  const [settled, setSettled] = React.useState(text)
  React.useEffect(() => {
    const timer = setTimeout(() => setSettled(text), delay)
    return () => clearTimeout(timer)
  }, [text, delay])
  return settled
}

export interface MigrationPreviewProps extends Omit<React.ComponentProps<"section">, "defaultValue">, MigrationContext {
  /** Controlled migration SQL (Postgres). */
  value?: string
  /** Initial SQL when uncontrolled. */
  defaultValue?: string
  /** Called with the new SQL when a fix is applied or undone. */
  onValueChange?: (value: string) => void
  /** Number format for row counts. */
  locale?: string
  /** Visible label; shorthand for `messages.label`. */
  label?: string
  /** Every visible string (`_one` keys are the singular forms). `{count}`, `{n}`, `{rows}`, `{detail}` are filled in. */
  messages?: Partial<MigrationPreviewMessages>
}

/**
 * A readback of a Postgres migration, one step at a time, before it runs:
 * what each step locks and for how long (with real row counts when you pass
 * them), what rewrites the table, what can't be undone (dropped tables and
 * columns, TRUNCATE), NOT NULL columns that will fail, renames that break code
 * mid-deploy, CONCURRENTLY inside a transaction and a missing lock_timeout.
 * Each fixable step gets the safer sequence in one tap, with undo.
 */
export function MigrationPreview({
  value,
  defaultValue = "",
  onValueChange,
  tableSizes,
  largeTableRows,
  inTransaction,
  locale,
  label,
  messages,
  className,
  ...props
}: MigrationPreviewProps) {
  const t = { ...DEFAULT_MESSAGES, ...messages, ...(label !== undefined && { label }) }
  const [inner, setInner] = React.useState(defaultValue)
  // Each entry is the SQL before a fix and the SQL the fix produced, so undo only offers itself while nothing else changed it.
  const [history, setHistory] = React.useState<{ before: string; after: string }[]>([])
  const list = React.useRef<HTMLOListElement>(null)
  const undoButton = React.useRef<HTMLButtonElement>(null)
  const refocus = React.useRef<number | null>(null)
  const baseId = React.useId()
  const sql = value ?? inner
  const canUndo = history.length > 0 && history[history.length - 1].after === sql
  const steps = React.useMemo(() => reviewMigration(sql, { tableSizes, largeTableRows, inTransaction }), [sql, tableSizes, largeTableRows, inTransaction])
  const irreversible = steps.filter((step) => step.irreversible).length
  const locking = steps.filter((step) => step.slow && step.lock !== "none" && step.risks.some((risk) => risk.severity === "warning")).length
  const risky = steps.some((step) => step.risks.some((risk) => risk.severity !== "info"))
  const summary = [steps.length === 1 ? t.steps_one : fill(t.steps, { count: steps.length }), irreversible && fill(t.irreversible, { count: irreversible }), locking && (locking === 1 ? t.locking_one : fill(t.locking, { count: locking }))].filter(Boolean).join(" · ")
  const announced = useSettled(steps.length ? summary : "")
  const number = new Intl.NumberFormat(locale, { notation: "compact", maximumFractionDigits: 1 })

  const update = (next: string) => {
    if (value === undefined) setInner(next)
    onValueChange?.(next)
  }
  // The tapped fix disappears with its risk, so focus goes to the next fix, or the step that changed.
  React.useEffect(() => {
    if (refocus.current === null) return
    const buttons = list.current?.querySelectorAll<HTMLButtonElement>("button[data-fix]") ?? []
    const target = buttons[Math.min(refocus.current, buttons.length - 1)] ?? undoButton.current
    target?.focus()
    refocus.current = null
  }, [sql])
  const applyFix = (step: MigrationStep, risk: MigrationRisk, button: HTMLElement) => {
    if (risk.fix === undefined) return
    refocus.current = [...(list.current?.querySelectorAll("button[data-fix]") ?? [])].indexOf(button)
    const next = replaceStep(sql, step, risk.fix)
    setHistory((prev) => [...(canUndo ? prev : []), { before: sql, after: next }])
    update(next)
  }
  const undo = () => {
    if (!canUndo) return
    setHistory((prev) => prev.slice(0, -1))
    refocus.current = 0
    update(history[history.length - 1].before)
  }

  return (
    <section data-slot="migration-preview" aria-labelledby={`${baseId}-title`} className={cn("grid w-full grid-cols-[minmax(0,1fr)] max-w-xl min-w-0 gap-2 text-sm", className)} {...props}>
      <header className="flex flex-wrap items-center justify-between gap-x-3 gap-y-1">
        <h3 id={`${baseId}-title`} className="font-medium">
          {t.label}
        </h3>
        {steps.length > 0 && (
          <p className={cn("flex items-center gap-1.5 text-xs", risky ? "text-muted-foreground" : "text-emerald-700 dark:text-emerald-400")}>
            {risky ? <TriangleAlert aria-hidden className="size-3.5 text-amber-600 dark:text-amber-400" /> : <CircleCheck aria-hidden className="size-3.5" />}
            {risky ? summary : t.clean}
          </p>
        )}
      </header>
      <span role="status" className="sr-only">
        {announced}
      </span>
      {steps.length === 0 ? (
        <p className="rounded-md border border-dashed px-3 py-4 text-center text-xs text-muted-foreground">{t.empty}</p>
      ) : (
        <ol ref={list} className="grid gap-2">
          {steps.map((step) => {
            const top = step.risks.reduce<MigrationRisk["severity"] | null>((max, risk) => (!max || rank[risk.severity] > rank[max] ? risk.severity : max), null)
            return (
              <li key={`${step.index}-${step.start}`} data-severity={top ?? undefined} className="grid min-w-0 gap-1.5 rounded-md border p-2 data-[severity=danger]:border-red-500/40 data-[severity=danger]:bg-red-500/5 data-[severity=warning]:border-amber-500/40 data-[severity=warning]:bg-amber-500/5">
                <div className="flex min-w-0 gap-2">
                  <span className="sr-only">{fill(t.step, { n: step.index + 1 })}</span>
                  <span aria-hidden className="grid size-5 shrink-0 place-items-center rounded-full bg-muted font-mono text-[11px] text-muted-foreground tabular-nums">
                    {step.index + 1}
                  </span>
                  <pre className="max-h-40 min-w-0 flex-1 overflow-auto font-mono text-xs leading-5 break-words whitespace-pre-wrap">{step.sql}</pre>
                </div>
                {(step.lock !== "none" || step.irreversible || step.rows !== undefined) && (
                  <div className="flex flex-wrap gap-1.5 pl-7">
                    {step.irreversible && (
                      <span className={cn(badge, "border-red-500/40 text-red-700 dark:text-red-300")}>
                        <Undo2 aria-hidden className="size-3" />
                        {t.cantUndo}
                      </span>
                    )}
                    {step.lock !== "none" && (
                      <span className={cn(badge, step.slow && (step.rows === undefined || step.risks.some((risk) => risk.severity === "warning")) ? "border-amber-500/40 text-amber-800 dark:text-amber-300" : "text-muted-foreground")}>
                        <Lock aria-hidden className="size-3" />
                        {t[step.lock === "writes" ? "lock-writes" : "lock-reads-writes"]}
                        {step.slow ? ` · ${t.slow}` : ` ${t.brief}`}
                      </span>
                    )}
                    {step.table && step.rows !== undefined && <span className={cn(badge, "font-mono font-normal text-muted-foreground")}>{`${step.table} · ${fill(t.rows, { rows: number.format(step.rows) })}`}</span>}
                  </div>
                )}
                {step.risks.length > 0 && (
                  <ul className="grid gap-1 pl-7 text-xs">
                    {step.risks.map((risk) => {
                      const Icon = icons[risk.severity]
                      const fixLabel = (t as Record<string, string>)[`fix-${risk.kind}`]
                      return (
                        <li key={risk.kind} className={cn("flex gap-1.5", tones[risk.severity])}>
                          <span className="flex h-6 shrink-0 items-center">
                            <Icon aria-hidden className="size-3.5" />
                          </span>
                          <span className="flex min-w-0 flex-wrap items-center gap-x-2 gap-y-1">
                            <span className="py-1 [overflow-wrap:anywhere]">{fill(t[risk.kind], { detail: risk.detail ?? "" })}</span>
                            {risk.fix !== undefined && fixLabel && (
                              <button type="button" data-fix="" onClick={(event) => applyFix(step, risk, event.currentTarget)} className={fixClass(risk.severity === "danger")}>
                                <WandSparkles aria-hidden className="size-3.5" />
                                {fixLabel}
                              </button>
                            )}
                          </span>
                        </li>
                      )
                    })}
                  </ul>
                )}
              </li>
            )
          })}
        </ol>
      )}
      {canUndo && (
        <button ref={undoButton} type="button" onClick={undo} className="inline-flex h-8 w-fit items-center gap-1.5 rounded-md border px-3 text-sm font-medium shadow-xs transition-colors outline-none hover:bg-accent focus-visible:ring-[3px] focus-visible:ring-ring/50 dark:bg-input/30">
          <Undo2 aria-hidden className="size-3.5" />
          {t.undo}
        </button>
      )}
    </section>
  )
}

export type MigrationRiskKind =
  | "drop-table" | "drop-column" | "truncate" | "delete-all" | "not-null-no-default" | "volatile-default" | "rewrite-column"
  | "type-change" | "set-not-null" | "index-blocking" | "drop-index-blocking" | "concurrently-in-tx" | "constraint-validate"
  | "unique-constraint" | "rename-column" | "rename-table" | "update-all" | "lock-timeout" | "reindex-blocking" | "table-rewrite"

/** What other sessions can't do while the step holds its lock. */
export type MigrationLock = "reads-writes" | "writes" | "none"

export interface MigrationRisk {
  kind: MigrationRiskKind
  severity: "danger" | "warning" | "info"
  /** Replacement SQL for the step (a safer sequence). Undefined: no safe automatic fix. */
  fix?: string
  /** Filled into the message: a column, an expression, a row count. */
  detail?: string
}

export interface MigrationStep {
  /** 0-based position in the migration. */
  index: number
  /** The statement as written, comments included. */
  sql: string
  /** Character range in the source. */
  start: number
  end: number
  /** Table the step acts on, unquoted, when one could be read. */
  table?: string
  /** Known row count for that table, from `tableSizes`. */
  rows?: number
  lock: MigrationLock
  /** Rewrites or scans every row while locked, so the lock lasts as long as the table is big. */
  slow: boolean
  /** Can't be reversed by a down migration: the data is gone. */
  irreversible: boolean
  risks: MigrationRisk[]
}

export interface MigrationContext {
  /** Row counts by table name (or schema.table). Unknown tables are treated as big. */
  tableSizes?: Record<string, number>
  /** Tables at or above this many rows count as big. */
  largeTableRows?: number
  /** Your runner wraps the file in a transaction (Rails, Prisma and Django do by default). */
  inTransaction?: boolean
}

/** Splits SQL into statements, ignoring ; inside strings (E'' escapes too), quoted names, dollar quotes and comments. Never throws. */
export function splitStatements(sql: string) {
  const statements: { sql: string; code: string; start: number; end: number }[] = []
  let code = ""
  let start = 0
  let i = 0
  const push = (end: number) => {
    const text = sql.slice(start, end)
    const lead = text.length - text.trimStart().length
    if (code.trim()) statements.push({ sql: text.trim(), code: code.replace(/\s+/g, " ").trim(), start: start + lead, end: start + text.trimEnd().length })
    code = ""
    start = end + 1
  }
  while (i < sql.length) {
    const ch = sql[i]
    const next = sql[i + 1]
    if (ch === "-" && next === "-") {
      const stop = sql.indexOf("\n", i)
      i = stop < 0 ? sql.length : stop
    } else if (ch === "/" && next === "*") {
      const stop = sql.indexOf("*/", i + 2)
      i = stop < 0 ? sql.length : stop + 2
      code += " "
    } else if (ch === "'") {
      // E'it\'s' strings allow backslash escapes; ordinary strings only escape by doubling the quote.
      const escapes = /[eE]/.test(sql[i - 1] ?? "") && !/[\w$]/.test(sql[i - 2] ?? "")
      let j = i + 1
      while (j < sql.length && !(sql[j] === "'" && sql[j + 1] !== "'")) j += sql[j] === "'" || (escapes && sql[j] === "\\") ? 2 : 1
      code += "'?'"
      i = j + 1
    } else if (ch === '"') {
      const stop = sql.indexOf('"', i + 1)
      code += sql.slice(i, stop < 0 ? sql.length : stop + 1)
      i = stop < 0 ? sql.length : stop + 1
    } else if (ch === "$" && !/[\w$]/.test(sql[i - 1] ?? "") && /^\$(?:[A-Za-z_]\w*)?\$/.test(sql.slice(i))) {
      const tag = sql.slice(i).match(/^\$(?:[A-Za-z_]\w*)?\$/)?.[0] ?? "$$"
      const stop = sql.indexOf(tag, i + tag.length)
      code += "'?'"
      i = stop < 0 ? sql.length : stop + tag.length
    } else if (ch === ";") {
      push(i)
      i++
    } else {
      code += ch
      i++
    }
  }
  push(sql.length)
  return statements
}

const NAME = String.raw`(?:"[^"]+"|[\w$]+)(?:\.(?:"[^"]+"|[\w$]+))?`
const unquote = (name: string) => name.replace(/"/g, "")
const VOLATILE = /\b(clock_timestamp|random|gen_random_uuid|uuid_generate_v\d\w*|nextval|timeofday)\s*\(/i
const re = (source: string) => new RegExp(source, "i")

/** Splits "ADD COLUMN a int, DROP COLUMN b" into its actions, ignoring commas inside parentheses. */
function splitActions(actions: string) {
  const parts: string[] = []
  let depth = 0
  let from = 0
  for (let i = 0; i < actions.length; i++) {
    if (actions[i] === "(") depth++
    else if (actions[i] === ")") depth = Math.max(0, depth - 1)
    else if (actions[i] === "," && depth === 0 && /^\s*(ADD|DROP|ALTER|RENAME|SET|VALIDATE)\b/i.test(actions.slice(i + 1))) {
      parts.push(actions.slice(from, i).trim())
      from = i + 1
    }
  }
  parts.push(actions.slice(from).trim())
  return parts.filter(Boolean)
}

/** Reads a Postgres migration step by step: what each one locks, what it rewrites, and what can't be undone. */
export function reviewMigration(sql: string, { tableSizes = {}, largeTableRows = 1_000_000, inTransaction = false }: MigrationContext = {}): MigrationStep[] {
  const statements = splitStatements(sql)
  let inTx = inTransaction
  const steps = statements.map(({ sql: text, code, start, end }, index): MigrationStep => {
    const step: MigrationStep = { index, sql: text, start, end, lock: "none", slow: false, irreversible: false, risks: [] }
    const add = (kind: MigrationRiskKind, severity: MigrationRisk["severity"], extra: Partial<MigrationRisk> = {}) => step.risks.push({ kind, severity, ...extra })
    if (/^(BEGIN|START TRANSACTION)\b/i.test(code)) inTx = true
    if (/^(COMMIT|END|ROLLBACK)\b/i.test(code)) inTx = inTransaction
    const alter = code.match(re(`^ALTER TABLE (?:IF EXISTS )?(?:ONLY )?(${NAME}) (.*)$`))
    const target =
      alter?.[1] ??
      code.match(re(`^(?:DROP TABLE (?:IF EXISTS )?|TRUNCATE (?:TABLE )?|DELETE FROM |UPDATE (?:ONLY )?|REINDEX (?:\\([^)]*\\) )?TABLE (?:CONCURRENTLY )?|VACUUM (?:FULL|\\([^)]*\\bFULL\\b[^)]*\\)) (?:\\w+ )*?|CLUSTER (?:VERBOSE )?)(${NAME})`))?.[1] ??
      code.match(re(`^CREATE (?:UNIQUE )?INDEX .*?\\bON (?:ONLY )?(${NAME})`))?.[1]
    if (target) {
      step.table = unquote(target)
      const size = tableSizes[step.table] ?? tableSizes[step.table.split(".").pop() ?? ""]
      if (size !== undefined) step.rows = size
    }
    const big = step.rows === undefined || step.rows >= largeTableRows
    // CONCURRENTLY can't run inside a transaction, so offering it there would trade one problem for a failing step.
    const concurrently = (fix: string) => (inTx ? undefined : fix)
    const slow = (kind: MigrationRiskKind, extra: Partial<MigrationRisk> = {}) => {
      step.slow = true
      add(kind, big ? "warning" : "info", extra)
    }

    if (re(`^DROP TABLE`).test(code)) {
      step.lock = "reads-writes"
      step.irreversible = true
      add("drop-table", "danger")
    } else if (re(`^TRUNCATE`).test(code)) {
      step.lock = "reads-writes"
      step.irreversible = true
      add("truncate", "danger")
    } else if (re(`^DELETE FROM ${NAME}(?: (?:AS )?\\w+)?$`).test(code)) {
      step.irreversible = true
      add("delete-all", "danger")
    } else if (re(`^UPDATE (?:ONLY )?${NAME} .*\\bSET\\b`).test(code) && !/\bWHERE\b/i.test(code)) {
      if (big) add("update-all", "warning")
    } else if (/^CREATE (UNIQUE )?INDEX\b/i.test(code)) {
      if (/\bCONCURRENTLY\b/i.test(code)) {
        if (inTx) add("concurrently-in-tx", "danger")
      } else {
        step.lock = "writes"
        slow("index-blocking", { fix: concurrently(text.replace(/\bINDEX\b/i, "INDEX CONCURRENTLY")) })
      }
    } else if (/^DROP INDEX\b/i.test(code)) {
      if (/\bCONCURRENTLY\b/i.test(code)) {
        if (inTx) add("concurrently-in-tx", "danger")
      } else {
        step.lock = "reads-writes"
        add("drop-index-blocking", big ? "warning" : "info", { fix: concurrently(text.replace(/\bINDEX\b/i, "INDEX CONCURRENTLY")) })
      }
    } else if (/^REINDEX\b/i.test(code)) {
      if (/\bCONCURRENTLY\b/i.test(code)) {
        if (inTx) add("concurrently-in-tx", "danger")
      } else if (!/^REINDEX (\([^)]*\) )?(SYSTEM|DATABASE)\b/i.test(code)) {
        step.lock = "writes"
        slow("reindex-blocking", { fix: concurrently(text.replace(/\b(INDEX|TABLE|SCHEMA)\b/i, "$1 CONCURRENTLY")) })
      }
    } else if (/^(VACUUM (FULL\b|\([^)]*\bFULL\b)|CLUSTER\b)/i.test(code)) {
      step.lock = "reads-writes"
      slow("table-rewrite")
    } else if (alter) {
      const table = alter[1]
      const actions = splitActions(alter[2])
      // Rebuilt fixes only make sense for a single-action ALTER; the rest still get flagged.
      const single = actions.length === 1
      const leading = text.match(/^(?:\s*(?:--[^\n]*(?:\n|$)|\/\*[\s\S]*?\*\/))*\s*/)?.[0] ?? ""
      const rebuilt = (fix: string) => (single ? leading + fix : undefined)
      step.lock = actions.every((action) => /^VALIDATE CONSTRAINT\b/i.test(action)) ? "none" : actions.every((action) => /^ADD (CONSTRAINT \S+ )?FOREIGN KEY\b/i.test(action)) ? "writes" : "reads-writes"
      for (const action of actions) {
        const column = action.match(re(`^ADD (?:COLUMN )?(?:IF NOT EXISTS )?(?!CONSTRAINT\\b|FOREIGN KEY\\b|CHECK\\b|UNIQUE\\b|PRIMARY KEY\\b|EXCLUDE\\b)(${NAME}) (.+)$`))
        const addConstraint = action.match(re(`^ADD (?:CONSTRAINT (${NAME}) )?(FOREIGN KEY|CHECK|UNIQUE|PRIMARY KEY|EXCLUDE)\\b(.*)$`))
        if (/^RENAME COLUMN|^RENAME (?!TO\b|CONSTRAINT\b)/i.test(action)) add("rename-column", "warning", { detail: unquote(action.match(/^RENAME (?:COLUMN )?("?[\w$]+"?)/i)?.[1] ?? "") })
        else if (/^RENAME TO\b/i.test(action)) add("rename-table", "warning")
        else if (/^DROP (COLUMN )?(?!CONSTRAINT\b)/i.test(action)) {
          step.irreversible = true
          add("drop-column", "danger", { detail: unquote(action.match(re(`^DROP (?:COLUMN )?(?:IF EXISTS )?(${NAME})`))?.[1] ?? "") })
        } else if (addConstraint) {
          const [, name, type, rest] = addConstraint
          if (/^(UNIQUE|PRIMARY KEY)$/i.test(type) && !/\bUSING INDEX\b/i.test(rest)) {
            const cols = rest.match(/^\s*\(([^)]*)\)/)?.[1]
            slow("unique-constraint", name && cols && /UNIQUE/i.test(type) && !inTx ? { fix: rebuilt(`CREATE UNIQUE INDEX CONCURRENTLY ${unquote(name)}_idx ON ${table} (${cols});\nALTER TABLE ${table} ADD CONSTRAINT ${name} UNIQUE USING INDEX ${unquote(name)}_idx;`) } : {})
          } else if (/^(FOREIGN KEY|CHECK)$/i.test(type) && !/\bNOT VALID\b/i.test(rest)) {
            slow("constraint-validate", name && single ? { fix: `${text} NOT VALID;\nALTER TABLE ${table} VALIDATE CONSTRAINT ${name};` } : {})
          }
        } else if (column) {
          const [, name, definition] = column
          const type = definition.match(/^([\w ]+?(?:\([^)]*\))?(?:\[\])?)(?= NOT| NULL| DEFAULT| GENERATED| PRIMARY| UNIQUE| REFERENCES| CHECK| CONSTRAINT| COLLATE|$)/i)?.[1] ?? definition
          const fullDefault = text.match(/\bDEFAULT\s+([\s\S]+?)(?=\s+(?:NOT\s+NULL|NULL|CHECK|REFERENCES|UNIQUE|PRIMARY|CONSTRAINT|GENERATED)\b|\s*$)/i)?.[1]
          if (/\bNOT NULL\b/i.test(definition) && !/\bDEFAULT\b/i.test(definition) && !/\bGENERATED\b/i.test(definition)) {
            // The SET NOT NULL stays commented out: run here, before the backfill, it would fail just the same.
            add("not-null-no-default", step.rows === 0 ? "info" : "danger", { detail: unquote(name), fix: rebuilt(`-- Backfill ${unquote(name)} in batches, then in a later migration:\n-- ALTER TABLE ${table} ALTER COLUMN ${name} SET NOT NULL;\nALTER TABLE ${table} ADD COLUMN ${name} ${type}`) })
          } else if (/\bDEFAULT\b/i.test(definition) && VOLATILE.test(definition)) {
            const notNull = /\bNOT NULL\b/i.test(definition) ? `\n-- Once backfilled, in a later migration: ALTER TABLE ${table} ALTER COLUMN ${name} SET NOT NULL;` : ""
            slow("volatile-default", { detail: fullDefault, fix: fullDefault ? rebuilt(`ALTER TABLE ${table} ADD COLUMN ${name} ${type};\n-- New rows get the default; backfill old rows in batches.${notNull}\nALTER TABLE ${table} ALTER COLUMN ${name} SET DEFAULT ${fullDefault};`) : undefined })
          } else if (/\b(BIG|SMALL)?SERIAL\b|\bGENERATED\b.*\bSTORED\b|\bGENERATED\b.*\bIDENTITY\b/i.test(definition)) slow("rewrite-column", { detail: unquote(name) })
        } else if (/^ALTER (?:COLUMN )?\S+ (?:SET DATA )?TYPE\b/i.test(action)) slow("type-change", { detail: unquote(action.match(/^ALTER (?:COLUMN )?(\S+)/i)?.[1] ?? "") })
        else if (/^ALTER (?:COLUMN )?\S+ SET NOT NULL\b/i.test(action)) {
          const name = action.match(/^ALTER (?:COLUMN )?(\S+)/i)?.[1] ?? ""
          const check = `${unquote(table).split(".").pop()}_${unquote(name)}_not_null`
          slow("set-not-null", { detail: unquote(name), fix: rebuilt(`ALTER TABLE ${table} ADD CONSTRAINT ${check} CHECK (${name} IS NOT NULL) NOT VALID;\nALTER TABLE ${table} VALIDATE CONSTRAINT ${check};\nALTER TABLE ${table} ALTER COLUMN ${name} SET NOT NULL;`) })
        }
      }
    }
    return step
  })
  // Only a lock_timeout set before the first locking step protects it; one in a comment or at the end does nothing.
  const locking = steps.find((step) => step.lock !== "none")
  const guarded = locking && statements.slice(0, locking.index).some(({ code }) => /^SET (SESSION |LOCAL )?lock_timeout\b/i.test(code))
  if (locking && !guarded) locking.risks.unshift({ kind: "lock-timeout", severity: "warning", fix: `SET lock_timeout = '5s';\n${locking.sql}` })
  return steps
}

/** Replaces one step's statement in the source, keeping everything around it. */
export function replaceStep(sql: string, step: Pick<MigrationStep, "start" | "end">, replacement: string) {
  const body = replacement.replace(/;\s*$/, "")
  return sql.slice(0, step.start) + body + sql.slice(step.end)
}
